pub(crate) fn pc_font_id(mut cx: &mut crate::port::Cells, key: i32) -> i32 {
    // The evidence id of a font dictionary: its index in the order the
    // document first showed it (-1 past 512 fonts).
    let n: i32 = crate::port::cells_at(cx, C_NFONT);
    let mut i: i32 = 0;
    while i < n {
        if crate::port::cells_at(cx, C_FIDS + i) == key {
            return i;
        }
        i += 1;
    }
    if n >= MAX_FIDS {
        return -1;
    }
    crate::port::cells_set(cx, C_FIDS + n, key);
    crate::port::cells_set(cx, C_NFONT, n + 1);
    return n;
}
pub(crate) fn pc_ensure_font(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, mut out: &mut crate::port::Cells, mut f0: &mut crate::port::Cells, mut f1: &mut crate::port::Cells, mut f2: &mut crate::port::Cells, mut f3: &mut crate::port::Cells) -> i32 {
    // Make the current font (the graphics state's) resident in a slot and set
    // C_SLOT to it, -1 when there is none. A font is loaded once and kept; the
    // slot that has gone unused longest is the one replaced.
    let key: i32 = crate::port::cells_at(cx, C_CUR + G_FONT);
    let mut i: i32 = 0;
    let mut at: i32 = 0;
    let mut pick: i32 = 0;
    let mut best: i32 = 2147483647;
    let mut status: i32 = 0;
    let mut fid: i32 = 0;
    let mut clock: i32 = crate::port::cells_at(cx, C_CLOCK);
    if key == 0 {
        crate::port::cells_set(cx, C_SLOT, -1);
        return 0;
    }
    clock += 1;
    crate::port::cells_set(cx, C_CLOCK, clock);
    while i < 4 {
        at = C_SLOTS + (i * SLOT_STRIDE);
        if crate::port::cells_at(cx, at + S_KEY) == key {
            crate::port::cells_set(cx, at + S_USE, clock);
            crate::port::cells_set(cx, C_SLOT, i);
            return 0;
        }
        if crate::port::cells_at(cx, at + S_USE) < best {
            best = crate::port::cells_at(cx, at + S_USE);
            pick = i;
        }
        i += 1;
    }
    at = C_SLOTS + (pick * SLOT_STRIDE);
    status = pc_f_load(src, ar, dc, a, b, st, out, f0, f1, f2, f3, pick, key);
    if ps_missed(src) {
        crate::port::cells_set(cx, C_ABORT, 1);
        crate::port::cells_set(cx, at + S_KEY, 0);
        crate::port::cells_set(cx, C_SLOT, -1);
        return 0;
    }
    crate::port::cells_set(cx, at + S_KEY, key);
    crate::port::cells_set(cx, at + S_USE, clock);
    crate::port::cells_set(cx, at + S_STATUS, status);
    fid = pc_font_id(cx, key);
    crate::port::cells_set(cx, at + S_ID, fid);
    if status == 0 {
        crate::port::cells_set(cx, at + S_ASC, pc_f_q(f0, f1, f2, f3, pick, 0));
        crate::port::cells_set(cx, at + S_DESC, pc_f_q(f0, f1, f2, f3, pick, 1));
        crate::port::cells_set(cx, at + S_VERT, pc_f_q(f0, f1, f2, f3, pick, 2));
        crate::port::cells_set(cx, at + S_DW2V, pc_f_q(f0, f1, f2, f3, pick, 3));
        crate::port::cells_set(cx, at + S_DW2W, pc_f_q(f0, f1, f2, f3, pick, 4));
    } else {
        crate::port::cells_set(cx, at + S_ASC, 0);
        crate::port::cells_set(cx, at + S_DESC, 0);
        crate::port::cells_set(cx, at + S_VERT, 0);
    }
    crate::port::cells_set(cx, C_SLOT, pick);
    return 0;
}
pub(crate) fn pc_tf(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, ox: &mut crate::port::Cells, n: i32) -> i32 {
    // Tf: the font named by operand 0 from the current Resources, at the size of
    // operand 1. The dictionary is resolved here and loaded at the first glyph.
    let size: i64 = pc_num(ox, n, 1);
    let mut fh: i32 = 0;
    let mut raw: i32 = 0;
    fx_put(cx, C_CUR + G_FS, size);
    if (n >= 1) && (pc_kind(ox, 0) == K_NAME) {
        raw = pc_res_entry(src, ar, dc, a, b, st, cx, ox, pn_font(), 0);
        if raw != 0 {
            fh = pd_resolve(src, ar, dc, a, b, st, raw);
        }
    }
    if ps_missed(src) {
        crate::port::cells_set(cx, C_ABORT, 1);
        return 0;
    }
    if fh == 0 {
        pc_warn_set(cx, W_FONT);
    } else if pl_kind_of(ar, fh) != 7 {
        fh = 0;
        pc_warn_set(cx, W_FONT);
    }
    crate::port::cells_set(cx, C_CUR + G_FONT, fh);
    return 0;
}
pub(crate) fn pc_min4(p: i64, q: i64, r: i64, s: i64) -> i64 {
    let mut m: i64 = p;
    if q < m {
        m = q;
    }
    if r < m {
        m = r;
    }
    if s < m {
        m = s;
    }
    return m;
}
pub(crate) fn pc_max4(p: i64, q: i64, r: i64, s: i64) -> i64 {
    let mut m: i64 = p;
    if q > m {
        m = q;
    }
    if r > m {
        m = r;
    }
    if s > m {
        m = s;
    }
    return m;
}
pub(crate) fn pc_glyph(mut cx: &mut crate::port::Cells, mut gl: &mut crate::port::Cells, mut et: &mut crate::port::Cells, mut f0: &mut crate::port::Cells, mut f1: &mut crate::port::Cells, mut f2: &mut crate::port::Cells, mut f3: &mut crate::port::Cells, code: i32, ncode: i32) -> i32 {
    // One shown glyph: look the code up, put its cell in page space, record it,
    // advance the text position by its width, the character and word spacing.
    let slot: i32 = crate::port::cells_at(cx, C_SLOT);
    let fs: i64 = fx_get(cx, C_CUR + G_FS);
    let th: i64 = fx_get(cx, C_CUR + G_TH);
    let tc: i64 = fx_get(cx, C_CUR + G_TC);
    let tw: i64 = fx_get(cx, C_CUR + G_TW);
    let rise: i64 = fx_get(cx, C_CUR + G_RISE);
    let mut sat: i32 = 0;
    let mut cnt: i32 = 0;
    let mut cp0: i32 = -1;
    let mut how: i32 = 5;
    let mut w: i32 = -1;
    let mut asc: i32 = 0;
    let mut desc: i32 = 0;
    let mut vert: i32 = 0;
    let mut dwv: i32 = -100000;
    let mut fid: i32 = -1;
    let mut tstart: i32 = -1;
    let mut i: i32 = 0;
    let mut idx: i32 = 0;
    if slot >= 0 {
        sat = C_SLOTS + (slot * SLOT_STRIDE);
        fid = crate::port::cells_at(cx, sat + S_ID);
        if crate::port::cells_at(cx, sat + S_STATUS) == 0 {
            cnt = pc_f_map(f0, f1, f2, f3, slot, code);
            how = pc_f_how(f0, f1, f2, f3, slot);
            w = pc_f_width(f0, f1, f2, f3, slot, code);
            asc = crate::port::cells_at(cx, sat + S_ASC);
            desc = crate::port::cells_at(cx, sat + S_DESC);
            vert = crate::port::cells_at(cx, sat + S_VERT);
            dwv = crate::port::cells_at(cx, sat + S_DW2W);
        }
    }
    if cnt > 0 {
        cp0 = pc_f_cp(f0, f1, f2, f3, slot, 0);
    }
    // A composite font's ToUnicode may say U+0000 or U+FFFD for a glyph it has no value
    // for (Skia does, for the parts of a Devanagari conjunct): that is no value.
    if (cnt == 1) && ((cp0 == 0) || (cp0 == 65533)) {
        cnt = 0;
        cp0 = -1;
        how = 5;
    }
    if w < 0 {
        w = 50000;
        pc_warn_set(cx, W_WIDTH);
    }
    if (asc == 0) && (desc == 0) {
        asc = 800;
        desc = -200;
    }
    let wfx: i64 = fx_muldiv(w as i64, fs, 100000 as i64);
    let mut x0t: i64 = 0 as i64;
    let mut x1t: i64 = 0 as i64;
    let mut y0t: i64 = 0 as i64;
    let mut y1t: i64 = 0 as i64;
    if vert == 0 {
        x1t = fx_mul(wfx, th);
        y0t = (fx_muldiv(desc as i64, fs, 1000 as i64)).wrapping_add(rise);
        y1t = (fx_muldiv(asc as i64, fs, 1000 as i64)).wrapping_add(rise);
    } else {
        x0t = (0 as i64) - (wfx / (2 as i64));
        x1t = wfx / (2 as i64);
        y0t = (fx_muldiv(dwv as i64, fs, 100000 as i64)).wrapping_add(rise);
        y1t = rise;
    }
    let p0x: i64 = mx_x(cx, C_M, x0t, y0t);
    let p0y: i64 = mx_y(cx, C_M, x0t, y0t);
    let p1x: i64 = mx_x(cx, C_M, x1t, y0t);
    let p1y: i64 = mx_y(cx, C_M, x1t, y0t);
    let p2x: i64 = mx_x(cx, C_M, x0t, y1t);
    let p2y: i64 = mx_y(cx, C_M, x0t, y1t);
    let p3x: i64 = mx_x(cx, C_M, x1t, y1t);
    let p3y: i64 = mx_y(cx, C_M, x1t, y1t);
    let ma: i64 = fx_get(cx, C_M);
    let mb: i64 = fx_get(cx, C_M + 2);
    let mc: i64 = fx_get(cx, C_M + 4);
    let md: i64 = fx_get(cx, C_M + 6);
    let size: i32 = fx_round(fx_mul(fx_hypot(mc, md), fx_abs(fs)));
    let rot: i32 = fx_atan2((0 as i64) - mb, ma);
    let bline: i32 = fx_round(mx_y(cx, C_M, 0 as i64, rise));
    let g: i32 = gl_new(gl, crate::port::cells_at(cx, C_PAGE), cp0, fid, size, fx_round(pc_min4(p0x, p1x, p2x, p3x)), fx_round(pc_min4(p0y, p1y, p2y, p3y)), fx_round(pc_max4(p0x, p1x, p2x, p3x)), fx_round(pc_max4(p0y, p1y, p2y, p3y)));
    gl_set(gl, g, gf_how(), how);
    gl_set(gl, g, gf_baseline(), bline);
    gl_set(gl, g, gf_rot(), rot);
    gl_set(gl, g, gf_color(), crate::port::cells_at(cx, C_CUR + G_COLOR));
    gl_set(gl, g, gf_alpha(), crate::port::cells_at(cx, C_CUR + G_ALPHA));
    gl_set(gl, g, gf_mode(), crate::port::cells_at(cx, C_CUR + G_MODE));
    gl_set(gl, g, gf_artifact(), crate::port::cells_at(cx, C_CURART));
    gl_set(gl, g, gf_mcid(), crate::port::cells_at(cx, C_CURMCID));
    if cnt > 1 {
        i = 0;
        while i < cnt {
            idx = etx_append_cp(et, pc_f_cp(f0, f1, f2, f3, slot, i));
            if i == 0 {
                tstart = idx;
            }
            i += 1;
        }
        gl_set(gl, g, gf_tstart(), tstart);
        gl_set(gl, g, gf_tlen(), cnt);
    }
    // The advance: tx = (w0 * Tfs + Tc + Tw) * Th, or ty = w1 * Tfs + Tc + Tw.
    let mut adv: i64 = 0 as i64;
    if vert == 0 {
        adv = (wfx).wrapping_add(tc);
    } else {
        adv = (fx_muldiv(dwv as i64, fs, 100000 as i64)).wrapping_add(tc);
    }
    if (code == 32) && (ncode == 1) {
        adv = (adv).wrapping_add(tw);
    }
    if vert == 0 {
        pc_advance(cx, fx_mul(adv, th), 0 as i64);
    } else {
        pc_advance(cx, 0 as i64, adv);
    }
    return 0;
}
pub(crate) fn pc_show_str(mut cx: &mut crate::port::Cells, ox: &mut crate::port::Cells, mut gl: &mut crate::port::Cells, mut et: &mut crate::port::Cells, mut f0: &mut crate::port::Cells, mut f1: &mut crate::port::Cells, mut f2: &mut crate::port::Cells, mut f3: &mut crate::port::Cells, s: i32) -> i32 {
    // Show the string operand s: split it into codes by the font's codespace.
    let start: i32 = pc_ea(ox, s);
    let ln: i32 = pc_eb(ox, s);
    let slot: i32 = crate::port::cells_at(cx, C_SLOT);
    let mut okfont: i32 = 0;
    let mut i: i32 = 0;
    let mut n: i32 = 1;
    let mut code: i32 = 0;
    let mut k: i32 = 0;
    let mut b0: i32 = 0;
    let mut b1: i32 = -1;
    let mut b2: i32 = -1;
    let mut b3: i32 = -1;
    if slot >= 0 {
        if crate::port::cells_at(cx, (C_SLOTS + (slot * SLOT_STRIDE)) + S_STATUS) == 0 {
            okfont = 1;
        }
    }
    while i < ln {
        b0 = crate::port::cells_at(ox, start + i);
        b1 = -1;
        b2 = -1;
        b3 = -1;
        if (i + 1) < ln {
            b1 = crate::port::cells_at(ox, start + (i + 1));
        }
        if (i + 2) < ln {
            b2 = crate::port::cells_at(ox, start + (i + 2));
        }
        if (i + 3) < ln {
            b3 = crate::port::cells_at(ox, start + (i + 3));
        }
        n = 1;
        if okfont == 1 {
            n = pc_f_code_len(f0, f1, f2, f3, slot, b0, b1, b2, b3);
        }
        if n < 1 {
            n = 1;
        }
        if n > 4 {
            n = 4;
        }
        if (i + n) > ln {
            n = ln - i;
        }
        code = 0;
        k = 0;
        while k < n {
            if (n == 4) && ((k == 0) && (crate::port::cells_at(ox, start + i) >= 128)) {
                code = (crate::port::cells_at(ox, start + i) - 256) * 16777216;
            } else {
                code = (code * 256) + crate::port::cells_at(ox, start + (i + k));
            }
            k += 1;
        }
        pc_glyph(cx, gl, et, f0, f1, f2, f3, code, n);
        i += n;
    }
    return 0;
}
pub(crate) fn pc_show_arr(mut cx: &mut crate::port::Cells, ox: &mut crate::port::Cells, mut gl: &mut crate::port::Cells, mut et: &mut crate::port::Cells, mut f0: &mut crate::port::Cells, mut f1: &mut crate::port::Cells, mut f2: &mut crate::port::Cells, mut f3: &mut crate::port::Cells, s: i32) -> i32 {
    // TJ: strings and adjustments. An adjustment n moves the position by
    // -n/1000 of the font size (along x, scaled by Th; along y in vertical mode).
    let cnt: i32 = pc_ea(ox, s);
    let slot: i32 = crate::port::cells_at(cx, C_SLOT);
    let fs: i64 = fx_get(cx, C_CUR + G_FS);
    let th: i64 = fx_get(cx, C_CUR + G_TH);
    let mut vert: i32 = 0;
    let mut j: i32 = s + 1;
    let mut k: i32 = 0;
    let mut delta: i64 = 0 as i64;
    if slot >= 0 {
        vert = crate::port::cells_at(cx, (C_SLOTS + (slot * SLOT_STRIDE)) + S_VERT);
    }
    while j < ((s + 1) + cnt) {
        k = pc_kind(ox, j);
        if k == K_STR {
            pc_show_str(cx, ox, gl, et, f0, f1, f2, f3, j);
        }
        if k == K_NUM {
            delta = (0 as i64) - fx_muldiv(fx_mul(fx_join(pc_ea(ox, j), pc_eb(ox, j)), fs), 1 as i64, 1000 as i64);
            if vert == 0 {
                pc_advance(cx, fx_mul(delta, th), 0 as i64);
            } else {
                pc_advance(cx, 0 as i64, delta);
            }
        }
        j += pc_esize(ox, j);
    }
    return 0;
}
pub(crate) static PC_PDFDOC_TAB: [i32; 41] = [
    728, 711, 710, 729, 733, 731, 730, 732, 8226, 8224, 8225, 8230, 8212, 8211, 402, 8260,
    8249, 8250, 8722, 8240, 8222, 8220, 8221, 8216, 8217, 8218, 8482, 64257, 64258, 321, 338, 352,
    376, 381, 305, 322, 339, 353, 382, 65533, 8364
];
pub(crate) fn pc_pdfdoc(c: i32) -> i32 {
    // PDFDocEncoding (Annex D.2) to Unicode: Latin-1 except 0x18-0x1F, 0x80-0xA0.
    if (c >= 24) && (c <= 31) {
        return PC_PDFDOC_TAB[(c - 24) as usize];
    }
    if (c >= 128) && (c <= 160) {
        return PC_PDFDOC_TAB[(8 + (c - 128)) as usize];
    }
    return c;
}
pub(crate) fn pc_push_bytes(mut et: &mut crate::port::Cells, ox: &mut crate::port::Cells, start: i32, ln: i32) -> i32 {
    // A name's bytes as code points (Latin-1), into the evidence text. Answers
    // the index of the first.
    let at: i32 = crate::port::cells_len(et);
    let mut k: i32 = 0;
    while k < ln {
        etx_append_cp(et, crate::port::cells_at(ox, start + k));
        k += 1;
    }
    return at;
}
pub(crate) fn pc_push_entry(mut et: &mut crate::port::Cells, ox: &mut crate::port::Cells, i: i32) -> i32 {
    // The bytes of name operand i into the evidence text; the index of the first.
    let s: i32 = pc_ea(ox, i);
    let ln: i32 = pc_eb(ox, i);
    return pc_push_bytes(et, ox, s, ln);
}
pub(crate) fn pc_push_utf16(mut et: &mut crate::port::Cells, ox: &mut crate::port::Cells, start: i32, ln: i32, little: i32) -> i32 {
    // UTF-16 text from ox[start, start+ln) (after the byte order mark), into
    // the evidence text: surrogate pairs joined, a lone surrogate U+FFFD, and
    // the language escapes of PDF 2.0 (U+001B ... U+001B) dropped.
    let mut k: i32 = 0;
    let mut u: i32 = 0;
    let mut u2: i32 = 0;
    let mut skip: i32 = 0;
    while (k + 1) < ln {
        if little == 1 {
            u = crate::port::cells_at(ox, start + k) + (crate::port::cells_at(ox, start + (k + 1)) * 256);
        } else {
            u = (crate::port::cells_at(ox, start + k) * 256) + crate::port::cells_at(ox, start + (k + 1));
        }
        k += 2;
        if (u >= 55296) && (u <= 56319) && ((k + 1) < ln) {
            if little == 1 {
                u2 = crate::port::cells_at(ox, start + k) + (crate::port::cells_at(ox, start + (k + 1)) * 256);
            } else {
                u2 = (crate::port::cells_at(ox, start + k) * 256) + crate::port::cells_at(ox, start + (k + 1));
            }
            if (u2 >= 56320) && (u2 <= 57343) {
                u = 65536 + (((u - 55296) * 1024) + (u2 - 56320));
                k += 2;
            }
        }
        if u == 27 {
            skip = 1 - skip;
        } else if skip == 0 {
            etx_append_cp(et, u);
        }
    }
    return 0;
}
pub(crate) fn pc_push_utf8(mut et: &mut crate::port::Cells, ox: &mut crate::port::Cells, start: i32, ln: i32) -> i32 {
    let mut k: i32 = 0;
    let mut c: i32 = 0;
    let mut need: i32 = 0;
    let mut v: i32 = 0;
    let mut j: i32 = 0;
    let mut ok: i32 = 0;
    while k < ln {
        c = crate::port::cells_at(ox, start + k);
        k += 1;
        need = 0;
        v = c;
        if c >= 240 {
            need = 3;
            v = c - 240;
        } else if c >= 224 {
            need = 2;
            v = c - 224;
        } else if c >= 192 {
            need = 1;
            v = c - 192;
        }
        ok = 1;
        if (c >= 128) && (c < 192) {
            ok = 0;
        }
        if c > 247 {
            ok = 0;
        }
        j = 0;
        while (ok == 1) && (j < need) {
            if (k < ln) && ((crate::port::cells_at(ox, start + k) >= 128) && (crate::port::cells_at(ox, start + k) < 192)) {
                v = (v * 64) + (crate::port::cells_at(ox, start + k) - 128);
                k += 1;
            } else {
                ok = 0;
            }
            j += 1;
        }
        if ok == 1 {
            etx_append_cp(et, v);
        } else {
            etx_append_cp(et, 65533);
        }
    }
    return 0;
}
pub(crate) fn pc_push_text(mut et: &mut crate::port::Cells, ox: &mut crate::port::Cells, start: i32, ln: i32) -> i32 {
    // A PDF text string (UTF-16BE or LE with a byte order mark, UTF-8 with its
    // BOM, else PDFDocEncoding) into the evidence text. Answers the first index.
    let at: i32 = crate::port::cells_len(et);
    let mut k: i32 = 0;
    if (ln >= 2) && ((crate::port::cells_at(ox, start) == 254) && (crate::port::cells_at(ox, start + 1) == 255)) {
        pc_push_utf16(et, ox, start + 2, ln - 2, 0);
        return at;
    }
    if (ln >= 2) && ((crate::port::cells_at(ox, start) == 255) && (crate::port::cells_at(ox, start + 1) == 254)) {
        pc_push_utf16(et, ox, start + 2, ln - 2, 1);
        return at;
    }
    if (ln >= 3) && ((crate::port::cells_at(ox, start) == 239) && ((crate::port::cells_at(ox, start + 1) == 187) && (crate::port::cells_at(ox, start + 2) == 191))) {
        pc_push_utf8(et, ox, start + 3, ln - 3);
        return at;
    }
    while k < ln {
        etx_append_cp(et, pc_pdfdoc(crate::port::cells_at(ox, start + k)));
        k += 1;
    }
    return at;
}
pub(crate) fn pc_ar_fx64(ar: &mut crate::port::Cells, h: i32) -> i64 {
    let kind: i32 = pl_kind_of(ar, h);
    if kind == 2 {
        return fx_of_int(pl_int_value(ar, h));
    }
    if kind == 3 {
        return fx_of_real(pl_int_value(ar, h), pl_ref_gen(ar, h));
    }
    return 0 as i64;
}
pub(crate) fn pc_ingest_props(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, mut ox: &mut crate::port::Cells, dict: i32) -> i32 {
    // Copy the pairs of a /Properties dictionary that marked content reads
    // into the operand entries as a dictionary entry, so one reader serves an
    // inline property list and a named one. Answers the entry's index.
    let d: i32 = pc_ox_push(cx, ox, K_DICT, 0, 0, 0);
    let mut k: i32 = pl_first(ar, dict);
    let mut v: i32 = 0;
    let mut vr: i32 = 0;
    let mut want: i32 = 0;
    let mut kind: i32 = 0;
    let mut at: i32 = 0;
    let mut j: i32 = 0;
    let mut ln: i32 = 0;
    let mut fxv: i64 = 0 as i64;
    if d < 0 {
        return -1;
    }
    while k != 0 {
        v = pl_next(ar, k);
        want = 0;
        if pl_kind_of(ar, k) == 4 {
            if (pl_name_is(ar, k, pn_mcid()) == 1) || ((pl_name_is(ar, k, pn_actual_text()) == 1) || ((pl_name_is(ar, k, pn_alt()) == 1) || ((pl_name_is(ar, k, pn_e()) == 1) || ((pl_name_is(ar, k, pn_lang()) == 1) || ((pl_name_is(ar, k, pn_type()) == 1) || (pl_name_is(ar, k, pn_subtype()) == 1)))))) {
                want = 1;
            }
        }
        if (want == 1) && (v != 0) {
            vr = pd_resolve(src, ar, dc, a, b, st, v);
            kind = 0;
            if vr != 0 {
                kind = pl_kind_of(ar, vr);
            }
            if (kind == 2) || (kind == 3) {
                fxv = pc_ar_fx64(ar, vr);
                // The key, then the number.
                ln = pl_name_len(ar, k);
                at = crate::port::cells_len(ox);
                j = 0;
                while j < ln {
                    crate::port::cells_push(ox, pl_name_byte(ar, k, j));
                    j += 1;
                }
                pc_ox_push(cx, ox, K_NAME, at, ln, 0);
                pc_ox_push(cx, ox, K_NUM, fx_hi(fxv), fx_lo(fxv), 1);
            }
            if (kind == 4) || (kind == 5) {
                ln = pl_name_len(ar, k);
                at = crate::port::cells_len(ox);
                j = 0;
                while j < ln {
                    crate::port::cells_push(ox, pl_name_byte(ar, k, j));
                    j += 1;
                }
                pc_ox_push(cx, ox, K_NAME, at, ln, 0);
                ln = pl_str_len(ar, vr);
                at = crate::port::cells_len(ox);
                j = 0;
                if kind == 4 {
                    while j < ln {
                        crate::port::cells_push(ox, pl_name_byte(ar, vr, j));
                        j += 1;
                    }
                } else {
                    while j < ln {
                        crate::port::cells_push(ox, pl_str_byte(ar, vr, j));
                        j += 1;
                    }
                }
                if kind == 4 {
                    pc_ox_push(cx, ox, K_NAME, at, ln, 0);
                } else {
                    pc_ox_push(cx, ox, K_STR, at, ln, 0);
                }
            }
        }
        if v == 0 {
            k = 0;
        } else {
            k = pl_next(ar, v);
        }
    }
    crate::port::cells_set(ox, (d * 4) + 1, (crate::port::cells_at(cx, C_OXN) - d) - 1);
    return d;
}
pub(crate) fn pc_read_props(mut et: &mut crate::port::Cells, mut sp: &mut crate::port::Cells, ox: &mut crate::port::Cells, span: i32, d: i32) -> i32 {
    // Fill the span's fields from the dictionary entry d of the operands: MCID,
    // Type, Subtype, ActualText, Alt, E, Lang. Answers a code for the artifact's
    // class: 1 watermark, 2 background, 3 pagination, 4 layout, 5 another
    // named type or subtype, 0 none.
    let end: i32 = (d + 1) + pc_ea(ox, d);
    let mut j: i32 = d + 1;
    let mut v: i32 = 0;
    let mut ks: i32 = 0;
    let mut kl: i32 = 0;
    let mut vs: i32 = 0;
    let mut vl: i32 = 0;
    let mut vk: i32 = 0;
    let mut at: i32 = 0;
    let mut cls: i32 = 0;
    while j < end {
        v = j + 1;
        if (pc_kind(ox, j) == K_NAME) && (v < end) {
            ks = pc_ea(ox, j);
            kl = pc_eb(ox, j);
            vk = pc_kind(ox, v);
            vs = pc_ea(ox, v);
            vl = pc_eb(ox, v);
            if (pc_name_eq(ox, ks, kl, pn_mcid()) == 1) && (vk == K_NUM) {
                sp_set(sp, span, sf_mcid(), fx_round(fx_join(vs, vl)));
            }
            if (pc_name_eq(ox, ks, kl, pn_type()) == 1) && (vk == K_NAME) {
                at = pc_push_bytes(et, ox, vs, vl);
                sp_set(sp, span, sf_type(), at);
                sp_set(sp, span, sf_typelen(), vl);
                if pc_name_eq(ox, vs, vl, pn_pagination()) == 1 {
                    if cls == 0 {
                        cls = 3;
                    }
                }
                if pc_name_eq(ox, vs, vl, pn_layout()) == 1 {
                    if cls == 0 {
                        cls = 4;
                    }
                }
                if pc_name_eq(ox, vs, vl, pn_background()) == 1 {
                    if cls != 1 {
                        cls = 2;
                    }
                }
                if cls == 0 {
                    cls = 5;
                }
            }
            if (pc_name_eq(ox, ks, kl, pn_subtype()) == 1) && (vk == K_NAME) {
                at = pc_push_bytes(et, ox, vs, vl);
                sp_set(sp, span, sf_subtype(), at);
                sp_set(sp, span, sf_subtypelen(), vl);
                if pc_name_eq(ox, vs, vl, pn_watermark()) == 1 {
                    cls = 1;
                }
                if pc_name_eq(ox, vs, vl, pn_background()) == 1 {
                    if cls != 1 {
                        cls = 2;
                    }
                }
                if (pc_name_eq(ox, vs, vl, pn_header()) == 1) || (pc_name_eq(ox, vs, vl, pn_footer()) == 1) {
                    if (cls == 0) || (cls == 5) {
                        cls = 3;
                    }
                }
                if cls == 0 {
                    cls = 5;
                }
            }
            if (vk == K_STR) || (vk == K_NAME) {
                if pc_name_eq(ox, ks, kl, pn_actual_text()) == 1 {
                    at = pc_push_text(et, ox, vs, vl);
                    sp_set(sp, span, sf_actual(), at);
                    sp_set(sp, span, sf_actuallen(), crate::port::cells_len(et) - at);
                }
                if pc_name_eq(ox, ks, kl, pn_alt()) == 1 {
                    at = pc_push_text(et, ox, vs, vl);
                    sp_set(sp, span, sf_alt(), at);
                    sp_set(sp, span, sf_altlen(), crate::port::cells_len(et) - at);
                }
                if pc_name_eq(ox, ks, kl, pn_e()) == 1 {
                    at = pc_push_text(et, ox, vs, vl);
                    sp_set(sp, span, sf_exp(), at);
                    sp_set(sp, span, sf_explen(), crate::port::cells_len(et) - at);
                }
                if pc_name_eq(ox, ks, kl, pn_lang()) == 1 {
                    at = pc_push_text(et, ox, vs, vl);
                    sp_set(sp, span, sf_lang(), at);
                    sp_set(sp, span, sf_langlen(), crate::port::cells_len(et) - at);
                }
            }
            j = v + pc_esize(ox, v);
        } else {
            j += pc_esize(ox, j);
        }
    }
    return cls;
}
pub(crate) fn pc_mc_recompute(mut cx: &mut crate::port::Cells, sp: &mut crate::port::Cells) -> i32 {
    // The innermost MCID and artifact class in force: walk the open spans.
    let mut t: i32 = crate::port::cells_at(cx, C_MCTOP);
    let mut mcid: i32 = -1;
    let mut art: i32 = 0;
    let mut guard: i32 = 0;
    let mut m: i32 = 0;
    while (t >= 0) && (guard <= MAX_MC) {
        if mcid < 0 {
            m = sp_get(sp, t, sf_mcid());
            if m >= 0 {
                mcid = m;
            }
        }
        if art == 0 {
            art = sp_get(sp, t, sf_artifact());
        }
        t = sp_get(sp, t, sf_parent());
        guard += 1;
    }
    crate::port::cells_set(cx, C_CURMCID, mcid);
    crate::port::cells_set(cx, C_CURART, art);
    return 0;
}
pub(crate) fn pc_mc_pop(mut cx: &mut crate::port::Cells, mut sp: &mut crate::port::Cells, gl: &mut crate::port::Cells, unterminated: i32) -> i32 {
    // Close the innermost open span: its glyphs are those shown since it opened.
    let t: i32 = crate::port::cells_at(cx, C_MCTOP);
    if t < 0 {
        return 0;
    }
    let g: i32 = gl_count(gl);
    let gf: i32 = sp_get(sp, t, sf_gfirst());
    let par: i32 = sp_get(sp, t, sf_parent());
    sp_set(sp, t, sf_gcount(), g - gf);
    if unterminated == 1 {
        let fl: i32 = sp_get(sp, t, sf_flags());
        sp_set(sp, t, sf_flags(), fl | mc_unterminated());
    }
    crate::port::cells_set(cx, C_MCTOP, par);
    crate::port::cells_set(cx, C_MCDEPTH, crate::port::cells_at(cx, C_MCDEPTH) - 1);
    pc_mc_recompute(cx, sp);
    return 0;
}
pub(crate) fn pc_mc_begin(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, mut ox: &mut crate::port::Cells, mut gl: &mut crate::port::Cells, mut et: &mut crate::port::Cells, mut sp: &mut crate::port::Cells, n: i32, props: i32) -> i32 {
    // BMC / BDC: open a span with the tag of operand 0 and, for BDC, the
    // properties of operand 1 (an inline dictionary, or a name in /Properties).
    let depth: i32 = crate::port::cells_at(cx, C_MCDEPTH);
    let mut tstart: i32 = 0;
    let mut tlen: i32 = 0;
    let mut span: i32 = 0;
    let mut d: i32 = -1;
    let mut cls: i32 = 0;
    let mut raw: i32 = 0;
    let mut dh: i32 = 0;
    let mut isart: i32 = 0;
    let mut flags: i32 = 0;
    if depth >= MAX_MC {
        crate::port::cells_set(cx, C_MCOVER, crate::port::cells_at(cx, C_MCOVER) + 1);
        pc_warn_set(cx, W_MC);
        return 0;
    }
    tstart = crate::port::cells_len(et);
    if (n >= 1) && (pc_kind(ox, 0) == K_NAME) {
        tstart = pc_push_entry(et, ox, 0);
        tlen = pc_eb(ox, 0);
        if pc_entry_name_is(ox, 0, pn_artifact()) == 1 {
            isart = 1;
        }
    }
    span = sp_new(sp, crate::port::cells_at(cx, C_PAGE), tstart, tlen, crate::port::cells_at(cx, C_MCTOP), gl_count(gl));
    sp_set(sp, span, sf_stm(), crate::port::cells_at(cx, C_STM));
    if isart == 1 {
        sp_set(sp, span, sf_artifact(), ar_other());
    }
    if (props == 1) && (n >= 2) {
        if pc_kind(ox, 1) == K_DICT {
            d = 1;
            flags = mc_inline();
        }
        if pc_kind(ox, 1) == K_NAME {
            raw = pc_res_entry(src, ar, dc, a, b, st, cx, ox, pn_properties(), 1);
            if raw != 0 {
                dh = pd_resolve(src, ar, dc, a, b, st, raw);
            }
            if ps_missed(src) {
                crate::port::cells_set(cx, C_ABORT, 1);
            }
            if (dh != 0) && (pl_kind_of(ar, dh) == 7) {
                d = pc_ingest_props(src, ar, dc, a, b, st, cx, ox, dh);
                flags = mc_resource();
            } else {
                flags = mc_unresolved();
                pc_warn_set(cx, W_PROPS);
            }
        }
        sp_set(sp, span, sf_flags(), flags);
        if d >= 0 {
            cls = pc_read_props(et, sp, ox, span, d);
            if isart == 1 {
                if cls == 1 {
                    sp_set(sp, span, sf_artifact(), ar_watermark());
                }
                if cls == 2 {
                    sp_set(sp, span, sf_artifact(), ar_background());
                }
                if cls == 3 {
                    sp_set(sp, span, sf_artifact(), ar_pagination());
                }
                if cls == 4 {
                    sp_set(sp, span, sf_artifact(), ar_layout());
                }
            }
        }
    }
    crate::port::cells_set(cx, C_MCTOP, span);
    crate::port::cells_set(cx, C_MCDEPTH, depth + 1);
    pc_mc_recompute(cx, sp);
    return 0;
}
pub(crate) fn pc_mc_end(mut cx: &mut crate::port::Cells, mut sp: &mut crate::port::Cells, gl: &mut crate::port::Cells) -> i32 {
    // EMC: close the innermost span this stream opened; a BDC that was too deep
    // to record is balanced first; an EMC with nothing to close is ignored.
    let over: i32 = crate::port::cells_at(cx, C_MCOVER);
    if over > 0 {
        crate::port::cells_set(cx, C_MCOVER, over - 1);
        return 0;
    }
    if crate::port::cells_at(cx, C_MCDEPTH) <= crate::port::cells_at(cx, C_MCBASE) {
        pc_warn_set(cx, W_MC);
        return 0;
    }
    return pc_mc_pop(cx, sp, gl, 0);
}
pub(crate) fn pc_skip_inline(mut cx: &mut crate::port::Cells, cs: &mut crate::port::Cells) -> i32 {
    // BI: skip to the end of the inline image: find `ID` and its one white
    // space, then the first `EI` that stands alone (white space before and white
    // space or the end after). Binary data rarely contains one; if it does the
    // rest is read as operators and skipped as unknown ones.
    let end: i32 = crate::port::cells_at(cx, C_END);
    let mut p: i32 = crate::port::cells_at(cx, C_POS);
    let mut found: i32 = 0;
    while ((p + 2) < end) && (found == 0) {
        if (pc_ws(crate::port::cells_at(cs, p)) == 1) && ((crate::port::cells_at(cs, p + 1) == 73) && ((crate::port::cells_at(cs, p + 2) == 68) && (((p + 3) >= end) || (pc_ws(crate::port::cells_at(cs, p + 3)) == 1)))) {
            found = 1;
            p += 4;
        } else {
            p += 1;
        }
    }
    if found == 0 {
        crate::port::cells_set(cx, C_POS, end);
        return 0;
    }
    found = 0;
    while ((p + 1) < end) && (found == 0) {
        if (crate::port::cells_at(cs, p) == 69) && ((crate::port::cells_at(cs, p + 1) == 73) && (((p == 0) || (pc_ws(crate::port::cells_at(cs, p - 1)) == 1)) && (((p + 2) >= end) || (pc_ws(crate::port::cells_at(cs, p + 2)) == 1)))) {
            found = 1;
            p += 2;
        } else {
            p += 1;
        }
    }
    if found == 0 {
        p = end;
    }
    crate::port::cells_set(cx, C_POS, p);
    return 0;
}
pub(crate) fn pc_append_stream(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, mut out: &mut crate::port::Cells, mut cs: &mut crate::port::Cells, sh: i32) -> i32 {
    // Decode stream sh and append its bytes (and a line feed) to `cs`. Answers
    // the filter chain's status (0 ok), or -1 when the source missed.
    let status: i32 = pd_stream_data(src, ar, dc, a, b, st, sh, out);
    let n: i32 = crate::port::cells_len(out);
    let mut i: i32 = 0;
    if ps_missed(src) {
        crate::port::cells_set(cx, C_ABORT, 1);
        return -1;
    }
    if status != 0 {
        pc_warn_set(cx, W_STREAM);
        crate::port::cells_set(cx, C_SSTAT, status);
    }
    while i < n {
        crate::port::cells_push(cs, crate::port::cells_at(out, i));
        i += 1;
    }
    crate::port::cells_push(cs, 10);
    return status;
}
pub(crate) fn pc_do(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, mut ox: &mut crate::port::Cells, mut cs: &mut crate::port::Cells, mut out: &mut crate::port::Cells, mut f0: &mut crate::port::Cells, mut f1: &mut crate::port::Cells, mut f2: &mut crate::port::Cells, mut f3: &mut crate::port::Cells, mut gl: &mut crate::port::Cells, mut et: &mut crate::port::Cells, mut sp: &mut crate::port::Cells, n: i32) -> i32 {
    // Do: run the Form XObject named by operand 0. Images and everything that is
    // not a form are skipped. The form's /Matrix is concatenated to the CTM, its
    // /Resources replace the current ones (else they are inherited), and it runs
    // inside its own `q`/`Q`.
    if n < 1 {
        return 0;
    }
    if pc_kind(ox, 0) != K_NAME {
        return 0;
    }
    let raw: i32 = pc_res_entry(src, ar, dc, a, b, st, cx, ox, pn_x_object(), 0);
    let mut objnum: i32 = 0;
    let mut xh: i32 = 0;
    let mut sub: i32 = 0;
    let mut fd: i32 = 0;
    let mut i: i32 = 0;
    let mut mat: i32 = 0;
    let mut el: i32 = 0;
    let mut got: i32 = 0;
    let mut res: i32 = 0;
    let mut oldres: i32 = 0;
    let mut oldstm: i32 = 0;
    let mut start: i32 = 0;
    let mut endcs: i32 = 0;
    let mut status: i32 = 0;
    if ps_missed(src) {
        crate::port::cells_set(cx, C_ABORT, 1);
        return 0;
    }
    if raw == 0 {
        pc_warn_set(cx, W_FORM);
        return 0;
    }
    if pl_kind_of(ar, raw) == 9 {
        objnum = pl_int_value(ar, raw);
    }
    xh = pd_resolve(src, ar, dc, a, b, st, raw);
    if ps_missed(src) {
        crate::port::cells_set(cx, C_ABORT, 1);
        return 0;
    }
    if xh == 0 {
        pc_warn_set(cx, W_FORM);
        return 0;
    }
    if pl_kind_of(ar, xh) != 8 {
        return 0;
    }
    sub = pd_dget(src, ar, dc, a, b, st, xh, pn_subtype());
    if ps_missed(src) {
        crate::port::cells_set(cx, C_ABORT, 1);
        return 0;
    }
    if sub == 0 {
        return 0;
    }
    if pl_name_is(ar, sub, pn_form()) == 0 {
        return 0;
    }
    // Depth and cycles: a form deeper than FORM_DEPTH, or already running, is skipped.
    fd = crate::port::cells_at(cx, C_FDEPTH);
    if (fd >= MAX_FORMS) || (fd >= crate::port::cells_at(cx, C_FLIM)) {
        pc_warn_set(cx, W_DEPTH);
        return 0;
    }
    if objnum != 0 {
        while i < fd {
            if crate::port::cells_at(cx, C_FSTACK + i) == objnum {
                pc_warn_set(cx, W_DEPTH);
                return 0;
            }
            i += 1;
        }
    }
    // Its /Matrix (six numbers, else the identity).
    mx_ident(cx, C_TMP);
    mat = pd_dget(src, ar, dc, a, b, st, xh, pn_matrix());
    if (mat != 0) && (pl_kind_of(ar, mat) == 6) {
        el = pl_first(ar, mat);
        got = 0;
        while (el != 0) && (got < 6) {
            fx_put(cx, C_TMP + (got * 2), pc_ar_fx64(ar, el));
            el = pl_next(ar, el);
            got += 1;
        }
        if got < 6 {
            mx_ident(cx, C_TMP);
        }
    }
    res = pd_dget(src, ar, dc, a, b, st, xh, pn_resources());
    oldres = crate::port::cells_at(cx, C_RES);
    oldstm = crate::port::cells_at(cx, C_STM);
    if (res != 0) && (pl_kind_of(ar, res) == 7) {
        crate::port::cells_set(cx, C_RES, res);
    }
    start = crate::port::cells_len(cs);
    status = pc_append_stream(src, ar, dc, a, b, st, cx, out, cs, xh);
    if status == -1 {
        return 0;
    }
    pc_save(cx);
    mx_mul(cx, C_CUR + G_CTM, C_TMP, C_CUR + G_CTM);
    crate::port::cells_set(cx, C_FSTACK + fd, objnum);
    crate::port::cells_set(cx, C_FDEPTH, fd + 1);
    crate::port::cells_set(cx, C_STM, objnum);
    endcs = crate::port::cells_len(cs);
    pc_run(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, sp, start, endcs);
    crate::port::cells_set(cx, C_FDEPTH, fd);
    crate::port::cells_set(cx, C_STM, oldstm);
    crate::port::cells_set(cx, C_RES, oldres);
    pc_restore(cx);
    crate::port::cells_drop(cs, start);
    return 0;
}
pub(crate) fn pc_prep(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, mut out: &mut crate::port::Cells, mut f0: &mut crate::port::Cells, mut f1: &mut crate::port::Cells, mut f2: &mut crate::port::Cells, mut f3: &mut crate::port::Cells) -> i32 {
    // Before a string is shown: the font resident, and M = Tm x CTM current.
    pc_ensure_font(src, ar, dc, a, b, st, cx, out, f0, f1, f2, f3);
    pc_update_m(cx);
    if crate::port::cells_at(cx, C_SLOT) < 0 {
        pc_warn_set(cx, W_TEXT);
    }
    return 0;
}
pub(crate) fn pc_op(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, mut ox: &mut crate::port::Cells, mut cs: &mut crate::port::Cells, mut out: &mut crate::port::Cells, mut f0: &mut crate::port::Cells, mut f1: &mut crate::port::Cells, mut f2: &mut crate::port::Cells, mut f3: &mut crate::port::Cells, mut gl: &mut crate::port::Cells, mut et: &mut crate::port::Cells, mut sp: &mut crate::port::Cells, op: i32, n: i32) -> i32 {
    // Execute one operator; `ox` holds its n operands. Unknown operators do
    // nothing (their operands are dropped by the caller).
    if op == OP_SAVE {
        pc_save(cx);
        return 0;
    }
    if op == OP_RESTORE {
        pc_restore(cx);
        return 0;
    }
    if op == OP_CM {
        if n >= 6 {
            mx_set(cx, C_TMP, pc_num(ox, n, 0), pc_num(ox, n, 1), pc_num(ox, n, 2), pc_num(ox, n, 3), pc_num(ox, n, 4), pc_num(ox, n, 5));
            mx_mul(cx, C_CUR + G_CTM, C_TMP, C_CUR + G_CTM);
        }
        return 0;
    }
    if op == OP_BT {
        mx_ident(cx, C_TM);
        mx_ident(cx, C_TLM);
        crate::port::cells_set(cx, C_INTEXT, 1);
        return 0;
    }
    if op == OP_ET {
        crate::port::cells_set(cx, C_INTEXT, 0);
        return 0;
    }
    if op == OP_TF {
        pc_tf(src, ar, dc, a, b, st, cx, ox, n);
        return 0;
    }
    if op == OP_TCHAR {
        fx_put(cx, C_CUR + G_TC, pc_num(ox, n, 0));
        return 0;
    }
    if op == OP_TWORD {
        fx_put(cx, C_CUR + G_TW, pc_num(ox, n, 0));
        return 0;
    }
    if op == OP_TSCALE {
        fx_put(cx, C_CUR + G_TH, fx_muldiv(pc_num(ox, n, 0), 1 as i64, 100 as i64));
        return 0;
    }
    if op == OP_TLEAD {
        fx_put(cx, C_CUR + G_TL, pc_num(ox, n, 0));
        return 0;
    }
    if op == OP_TRISE {
        fx_put(cx, C_CUR + G_RISE, pc_num(ox, n, 0));
        return 0;
    }
    if op == OP_TMODE {
        crate::port::cells_set(cx, C_CUR + G_MODE, fx_round(pc_num(ox, n, 0)));
        return 0;
    }
    if op == OP_TD {
        pc_td(cx, pc_num(ox, n, 0), pc_num(ox, n, 1));
        return 0;
    }
    if op == OP_TDL {
        fx_put(cx, C_CUR + G_TL, (0 as i64) - pc_num(ox, n, 1));
        pc_td(cx, pc_num(ox, n, 0), pc_num(ox, n, 1));
        return 0;
    }
    if op == OP_TM {
        if n >= 6 {
            pc_set_tm(cx, pc_num(ox, n, 0), pc_num(ox, n, 1), pc_num(ox, n, 2), pc_num(ox, n, 3), pc_num(ox, n, 4), pc_num(ox, n, 5));
        }
        return 0;
    }
    if op == OP_TSTAR {
        pc_next_line(cx);
        return 0;
    }
    if op == OP_SHOW {
        if (n >= 1) && (pc_kind(ox, 0) == K_STR) {
            pc_prep(src, ar, dc, a, b, st, cx, out, f0, f1, f2, f3);
            pc_show_str(cx, ox, gl, et, f0, f1, f2, f3, 0);
        }
        return 0;
    }
    if op == OP_SHOWARR {
        if (n >= 1) && (pc_kind(ox, 0) == K_ARR) {
            pc_prep(src, ar, dc, a, b, st, cx, out, f0, f1, f2, f3);
            pc_show_arr(cx, ox, gl, et, f0, f1, f2, f3, 0);
        }
        return 0;
    }
    if op == OP_QUOTE {
        if (n >= 1) && (pc_kind(ox, 0) == K_STR) {
            pc_next_line(cx);
            pc_prep(src, ar, dc, a, b, st, cx, out, f0, f1, f2, f3);
            pc_show_str(cx, ox, gl, et, f0, f1, f2, f3, 0);
        }
        return 0;
    }
    if op == OP_DQUOTE {
        if (n >= 3) && (pc_kind(ox, 2) == K_STR) {
            fx_put(cx, C_CUR + G_TW, pc_num(ox, n, 0));
            fx_put(cx, C_CUR + G_TC, pc_num(ox, n, 1));
            pc_next_line(cx);
            pc_prep(src, ar, dc, a, b, st, cx, out, f0, f1, f2, f3);
            pc_show_str(cx, ox, gl, et, f0, f1, f2, f3, 2);
        }
        return 0;
    }
    if op == OP_DO {
        pc_do(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, sp, n);
        return 0;
    }
    if op == OP_BDC {
        pc_mc_begin(src, ar, dc, a, b, st, cx, ox, gl, et, sp, n, 1);
        return 0;
    }
    if op == OP_BMC {
        pc_mc_begin(src, ar, dc, a, b, st, cx, ox, gl, et, sp, n, 0);
        return 0;
    }
    if op == OP_EMC {
        pc_mc_end(cx, sp, gl);
        return 0;
    }
    if op == OP_BI {
        pc_skip_inline(cx, cs);
        return 0;
    }
    if (op == OP_GRAY) || ((op == OP_RGB) || ((op == OP_CMYK) || ((op == OP_SC) || (op == OP_SCN)))) {
        pc_set_color(cx, ox, n);
        return 0;
    }
    if op == OP_CS {
        crate::port::cells_set(cx, C_CUR + G_COLOR, 0);
        if (n >= 1) && (pc_kind(ox, 0) == K_NAME) {
            crate::port::cells_set(cx, C_CUR + G_FAM, 0);
            if pc_entry_name_is(ox, 0, pn_device_gray()) == 1 {
                crate::port::cells_set(cx, C_CUR + G_FAM, 1);
            }
            if pc_entry_name_is(ox, 0, pn_device_rgb()) == 1 {
                crate::port::cells_set(cx, C_CUR + G_FAM, 2);
            }
            if pc_entry_name_is(ox, 0, pn_device_cmyk()) == 1 {
                crate::port::cells_set(cx, C_CUR + G_FAM, 3);
            }
        }
        return 0;
    }
    if op == OP_GS {
        if (n >= 1) && (pc_kind(ox, 0) == K_NAME) {
            let raw: i32 = pc_res_entry(src, ar, dc, a, b, st, cx, ox, pn_ext_g_state(), 0);
            if raw != 0 {
                let gd: i32 = pd_resolve(src, ar, dc, a, b, st, raw);
                if gd != 0 {
                    let cav: i32 = pd_dget(src, ar, dc, a, b, st, gd, pn_ca());
                    if cav != 0 {
                        let al: i32 = fx_round(fx_mul(pc_ar_fx64(ar, cav), fx_of_int(1000)));
                        if al < 0 {
                            crate::port::cells_set(cx, C_CUR + G_ALPHA, 0);
                        } else if al > 1000 {
                            crate::port::cells_set(cx, C_CUR + G_ALPHA, 1000);
                        } else {
                            crate::port::cells_set(cx, C_CUR + G_ALPHA, al);
                        }
                    }
                }
            }
            if ps_missed(src) {
                crate::port::cells_set(cx, C_ABORT, 1);
            }
        }
        return 0;
    }
    return 0;
}
pub(crate) fn pc_run(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, mut ox: &mut crate::port::Cells, mut cs: &mut crate::port::Cells, mut out: &mut crate::port::Cells, mut f0: &mut crate::port::Cells, mut f1: &mut crate::port::Cells, mut f2: &mut crate::port::Cells, mut f3: &mut crate::port::Cells, mut gl: &mut crate::port::Cells, mut et: &mut crate::port::Cells, mut sp: &mut crate::port::Cells, start: i32, end: i32) -> i32 {
    // Run the content bytes cs[start, end): read operands, then execute each
    // operator. The caller's lexer position, graphics-state floor and marked-
    // content floor are kept and restored, so a form can run inside an operator.
    let oldpos: i32 = crate::port::cells_at(cx, C_POS);
    let oldend: i32 = crate::port::cells_at(cx, C_END);
    let oldgs: i32 = crate::port::cells_at(cx, C_GSBASE);
    let oldmcb: i32 = crate::port::cells_at(cx, C_MCBASE);
    let oldover: i32 = crate::port::cells_at(cx, C_MCOVER);
    let oldtop: i32 = crate::port::cells_at(cx, C_MCTOP);
    let mut r: i32 = 1;
    let mut opc: i32 = 0;
    let mut nop: i32 = 0;
    let mut ops: i32 = 0;
    crate::port::cells_set(cx, C_POS, start);
    crate::port::cells_set(cx, C_END, end);
    crate::port::cells_set(cx, C_GSBASE, crate::port::cells_at(cx, C_DEPTH));
    crate::port::cells_set(cx, C_MCBASE, crate::port::cells_at(cx, C_MCDEPTH));
    crate::port::cells_set(cx, C_MCOVER, 0);
    pc_ox_clear(cx, ox);
    while (r != 0) && (crate::port::cells_at(cx, C_ABORT) == 0) {
        r = pc_lex(cx, ox, cs);
        if r == 2 {
            ops = crate::port::cells_at(cx, C_OPS) + 1;
            crate::port::cells_set(cx, C_OPS, ops);
            if ops > crate::port::cells_at(cx, C_OPLIM) {
                crate::port::limit_breach(5, ops);
            }
            opc = crate::port::cells_at(cx, C_OP);
            nop = crate::port::cells_at(cx, C_OXN);
            pc_op(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, sp, opc, nop);
            pc_ox_clear(cx, ox);
        }
    }
    // What the stream left open: spans, graphics states.
    while crate::port::cells_at(cx, C_MCDEPTH) > crate::port::cells_at(cx, C_MCBASE) {
        pc_warn_set(cx, W_MC);
        pc_mc_pop(cx, sp, gl, 1);
    }
    while crate::port::cells_at(cx, C_DEPTH) > crate::port::cells_at(cx, C_GSBASE) {
        crate::port::cells_set(cx, C_DEPTH, crate::port::cells_at(cx, C_DEPTH) - 1);
    }
    crate::port::cells_set(cx, C_MCTOP, oldtop);
    pc_mc_recompute(cx, sp);
    crate::port::cells_set(cx, C_MCOVER, oldover);
    crate::port::cells_set(cx, C_MCBASE, oldmcb);
    crate::port::cells_set(cx, C_GSBASE, oldgs);
    crate::port::cells_set(cx, C_POS, oldpos);
    crate::port::cells_set(cx, C_END, oldend);
    return 0;
}
pub(crate) const WORD_GAP_PM: i32 = 160;
pub(crate) const WORD_BACK_PM: i32 = 400;
pub(crate) const OFFSET_PM: i32 = 450;
pub(crate) const LINE_BACK_PM: i32 = 600;
pub(crate) const LINE_GAP_PM: i32 = 2000;
pub(crate) fn pc_axis(rot: i32) -> i32 {
    // The writing axis a rotation is within three degrees of, else -1 (a glyph run
    // at another angle is measured along its own direction, `pc-rot-gap`).
    let a: i32 = ((rot + 4500) / 9000) % 4;
    let mut d: i32 = rot - (a * 9000);
    if d < 0 {
        d = 0 - d;
    }
    if d > 18000 {
        d = 36000 - d;
    }
    if d <= 300 {
        return a;
    }
    return -1;
}
pub(crate) fn pc_offset(gl: &mut crate::port::Cells, j: i32, axis: i32) -> i32 {
    // Where glyph j's baseline is across its writing axis, in centipoints.
    if axis == 1 {
        return gl_get(gl, j, gf_x1());
    }
    if axis == 3 {
        return gl_get(gl, j, gf_x0());
    }
    return gl_get(gl, j, gf_baseline());
}
pub(crate) fn pc_gap(gl: &mut crate::port::Cells, p: i32, g: i32, axis: i32) -> i32 {
    // The space along the axis between glyph p and the glyph g after it
    // (negative when they overlap or g is before p).
    if axis == 0 {
        return gl_get(gl, g, gf_x0()) - gl_get(gl, p, gf_x1());
    }
    if axis == 2 {
        return gl_get(gl, p, gf_x0()) - gl_get(gl, g, gf_x1());
    }
    if axis == 1 {
        return gl_get(gl, p, gf_y0()) - gl_get(gl, g, gf_y1());
    }
    return gl_get(gl, g, gf_y0()) - gl_get(gl, p, gf_y1());
}
pub(crate) fn pc_rot_gap(gl: &mut crate::port::Cells, p: i32, g: i32, size: i32) -> i32 {
    // For text at an arbitrary angle: the distance between glyph p's centre and
    // glyph g's, along the writing direction, less 60 percent of the size (the
    // two half-advances of adjacent letters), so it reads as `pc-gap` does.
    let rot: i32 = gl_get(gl, p, gf_rot());
    let ux: i64 = fx_cos(rot);
    let uy: i64 = (0 as i64) - fx_sin(rot);
    let dx2: i32 = (gl_get(gl, g, gf_x0()) + gl_get(gl, g, gf_x1())) - (gl_get(gl, p, gf_x0()) + gl_get(gl, p, gf_x1()));
    let dy2: i32 = (gl_get(gl, g, gf_y0()) + gl_get(gl, g, gf_y1())) - (gl_get(gl, p, gf_y0()) + gl_get(gl, p, gf_y1()));
    let al2: i64 = (fx_mul(fx_of_int(dx2), ux)).wrapping_add(fx_mul(fx_of_int(dy2), uy));
    return fx_round(al2 / (2 as i64)) - ((size * 600) / 1000);
}
pub(crate) fn pc_rot_off(gl: &mut crate::port::Cells, p: i32, g: i32) -> i32 {
    // The distance between the two glyphs' centres across the writing direction.
    let rot: i32 = gl_get(gl, p, gf_rot());
    let sn: i64 = fx_sin(rot);
    let cs: i64 = fx_cos(rot);
    let dx2: i32 = (gl_get(gl, g, gf_x0()) + gl_get(gl, g, gf_x1())) - (gl_get(gl, p, gf_x0()) + gl_get(gl, p, gf_x1()));
    let dy2: i32 = (gl_get(gl, g, gf_y0()) + gl_get(gl, g, gf_y1())) - (gl_get(gl, p, gf_y0()) + gl_get(gl, p, gf_y1()));
    let pe: i32 = fx_round((fx_mul(fx_of_int(dx2), sn)).wrapping_add(fx_mul(fx_of_int(dy2), cs)) / (2 as i64));
    if pe < 0 {
        return 0 - pe;
    }
    return pe;
}
pub(crate) fn pc_pair_gap(gl: &mut crate::port::Cells, p: i32, g: i32, axis: i32, size: i32) -> i32 {
    if axis < 0 {
        return pc_rot_gap(gl, p, g, size);
    }
    return pc_gap(gl, p, g, axis);
}
pub(crate) fn pc_pair_off(gl: &mut crate::port::Cells, p: i32, g: i32, axis: i32) -> i32 {
    // How far glyph g's baseline is from glyph p's, across the writing axis.
    if axis < 0 {
        return pc_rot_off(gl, p, g);
    }
    let d: i32 = pc_offset(gl, p, axis) - pc_offset(gl, g, axis);
    if d < 0 {
        return 0 - d;
    }
    return d;
}
pub(crate) fn pc_space_cp(cp: i32) -> i32 {
    // 1 for a code point that separates words: the spaces (U+0020, U+00A0,
    // U+1680, U+2000..200A, U+202F, U+205F, U+3000) and the tab.
    if (cp == 32) || ((cp == 160) || ((cp == 9) || ((cp == 5760) || ((cp == 8239) || ((cp == 8287) || (cp == 12288)))))) {
        return 1;
    }
    if (cp >= 8192) && (cp <= 8202) {
        return 1;
    }
    return 0;
}
pub(crate) fn pc_cl(v: i32) -> i32 {
    // Clamp a distance to +-1,000,000 centipoints so a per-mille product fits an I32.
    if v > 1000000 {
        return 1000000;
    }
    if v < -1000000 {
        return -1000000;
    }
    return v;
}
pub(crate) fn pc_rot_same(r1: i32, r2: i32) -> i32 {
    // 1 when two rotations (centi-degrees) agree to half a degree.
    let mut d: i32 = r1 - r2;
    if d < 0 {
        d = 0 - d;
    }
    if d > 18000 {
        d = 36000 - d;
    }
    if d <= 50 {
        return 1;
    }
    return 0;
}
pub(crate) fn pc_continues(gl: &mut crate::port::Cells, p: i32, g: i32) -> i32 {
    // 1 when glyph g continues the word glyph p is in: the same rotation, on the
    // same baseline (to 45 percent of the size: sub- and superscripts stay), and
    // the gap along the axis neither a word space nor a step back.
    let rot: i32 = gl_get(gl, p, gf_rot());
    let axis: i32 = pc_axis(rot);
    let size: i32 = gl_get(gl, g, gf_size());
    let sizep: i32 = gl_get(gl, p, gf_size());
    let mut sz: i32 = size;
    let mut gap: i32 = 0;
    let mut off: i32 = 0;
    if pc_rot_same(rot, gl_get(gl, g, gf_rot())) == 0 {
        return 0;
    }
    if sizep > sz {
        sz = sizep;
    }
    if sz > 200000 {
        sz = 200000;
    }
    off = pc_cl(pc_pair_off(gl, p, g, axis));
    if (off * 1000) > (sz * OFFSET_PM) {
        return 0;
    }
    gap = pc_cl(pc_pair_gap(gl, p, g, axis, sz));
    if (gap * 1000) > (sz * WORD_GAP_PM) {
        return 0;
    }
    if (gap * 1000) < (0 - (sz * WORD_BACK_PM)) {
        return 0;
    }
    return 1;
}
pub(crate) fn pc_cls(cp: i32) -> i32 {
    // A code point's strength for reordering right-to-left text: 1 strong right-to-left
    // (Hebrew, Arabic, Syriac, Thaana, N'Ko and their presentation forms), 2 a left-to-right
    // letter or a digit (Arabic-Indic digits are digits: they run left to right inside
    // right-to-left text), 0 neutral (punctuation, symbols, what has no value).
    if cp < 33 {
        return 0;
    }
    if ((cp >= 48) && (cp <= 57)) || (((cp >= 1632) && (cp <= 1641)) || ((cp >= 1776) && (cp <= 1785))) {
        return 2;
    }
    if ((cp >= 1424) && (cp <= 2303)) || (((cp >= 64285) && (cp <= 65023)) || ((cp >= 65136) && (cp <= 65279))) {
        return 1;
    }
    if ((cp >= 65) && (cp <= 90)) || ((cp >= 97) && (cp <= 122)) {
        return 2;
    }
    if (cp >= 192) && ((cp < 8192) && (cp != 215)) {
        return 2;
    }
    if (cp >= 12352) && (cp < 65000) {
        return 2;
    }
    return 0;
}
pub(crate) fn pc_gcls(gl: &mut crate::port::Cells, j: i32) -> i32 {
    return pc_cls(gl_get(gl, j, gf_cp()));
}
pub(crate) fn pc_glyph_out(mut et: &mut crate::port::Cells, gl: &mut crate::port::Cells, j: i32) -> i32 {
    // Append glyph j's text (every code point it stands for, or U+FFFD) to the evidence text.
    let ts: i32 = gl_get(gl, j, gf_tstart());
    let tl: i32 = gl_get(gl, j, gf_tlen());
    let cp: i32 = gl_get(gl, j, gf_cp());
    let mut k: i32 = 0;
    let mut cpv: i32 = 0;
    if (ts >= 0) && (tl > 0) {
        while k < tl {
            cpv = crate::port::cells_at(et, ts + k);
            etx_append_cp(et, cpv);
            k += 1;
        }
        return 0;
    }
    if cp >= 0 {
        etx_append_cp(et, cp);
    } else {
        etx_append_cp(et, 65533);
    }
    return 0;
}
pub(crate) fn pc_emit_word(mut gl: &mut crate::port::Cells, mut et: &mut crate::port::Cells, mut wd: &mut crate::port::Cells, page: i32, gfst: i32, glst: i32) -> i32 {
    // Record glyphs [gfst, glst] as a word: the union of their boxes, their text, the
    // dominant font and size of the first, and `hidden-text` as its source when every
    // glyph is render mode 3. A right-to-left word whose glyphs run left to right on the
    // page (visual order, as Skia and most producers write them) has its TEXT written in
    // logical order: the glyphs reversed, with the runs of digits and Latin letters in it
    // turned back. The glyphs themselves stay as they were shown.
    let mut x0: i32 = gl_get(gl, gfst, gf_x0());
    let mut y0: i32 = gl_get(gl, gfst, gf_y0());
    let mut x1: i32 = gl_get(gl, gfst, gf_x1());
    let mut y1: i32 = gl_get(gl, gfst, gf_y1());
    let mut j: i32 = gfst;
    let mut tstart: i32 = -1;
    let mut visible: i32 = 0;
    let mut nr: i32 = 0;
    let mut nl: i32 = 0;
    let mut cl: i32 = 0;
    let mut rtlw: i32 = 0;
    let mut kk: i32 = 0;
    let mut m: i32 = 0;
    while j <= glst {
        if gl_get(gl, j, gf_x0()) < x0 {
            x0 = gl_get(gl, j, gf_x0());
        }
        if gl_get(gl, j, gf_y0()) < y0 {
            y0 = gl_get(gl, j, gf_y0());
        }
        if gl_get(gl, j, gf_x1()) > x1 {
            x1 = gl_get(gl, j, gf_x1());
        }
        if gl_get(gl, j, gf_y1()) > y1 {
            y1 = gl_get(gl, j, gf_y1());
        }
        if gl_get(gl, j, gf_mode()) != 3 {
            visible = 1;
        }
        cl = pc_gcls(gl, j);
        if cl == 1 {
            nr += 1;
        }
        if cl == 2 {
            nl += 1;
        }
        j += 1;
    }
    if (nr > nl) && (glst > gfst) {
        if pc_axis(gl_get(gl, gfst, gf_rot())) == 0 {
            if gl_get(gl, glst, gf_x0()) >= gl_get(gl, gfst, gf_x0()) {
                rtlw = 1;
            }
        }
    }
    tstart = crate::port::cells_len(et);
    if rtlw == 0 {
        j = gfst;
        while j <= glst {
            pc_glyph_out(et, gl, j);
            j += 1;
        }
    } else {
        j = glst;
        while j >= gfst {
            if pc_gcls(gl, j) == 2 {
                kk = j;
                while (kk > gfst) && (pc_gcls(gl, kk - 1) == 2) {
                    kk -= 1;
                }
                m = kk;
                while m <= j {
                    pc_glyph_out(et, gl, m);
                    m += 1;
                }
                j = kk - 1;
            } else {
                pc_glyph_out(et, gl, j);
                j -= 1;
            }
        }
    }
    let w: i32 = wd_new(wd, page, x0, y0, x1, y1, gfst, (glst - gfst) + 1);
    wd_set(wd, w, wf_tstart(), tstart);
    wd_set(wd, w, wf_tlen(), crate::port::cells_len(et) - tstart);
    wd_set(wd, w, wf_font(), gl_get(gl, gfst, gf_font()));
    wd_set(wd, w, wf_size(), gl_get(gl, gfst, gf_size()));
    if visible == 0 {
        wd_set(wd, w, wf_src(), sr_hidden_text());
    }
    j = gfst;
    while j <= glst {
        gl_set(gl, j, gf_word(), w);
        j += 1;
    }
    return w;
}
pub(crate) fn pc_swap_rows(mut wd: &mut crate::port::Cells, i: i32, j: i32) -> i32 {
    let mut k: i32 = 0;
    let mut u: i32 = 0;
    let mut v: i32 = 0;
    while k < 16 {
        u = crate::port::cells_at(wd, (i * 16) + k);
        v = crate::port::cells_at(wd, (j * 16) + k);
        crate::port::cells_set(wd, (i * 16) + k, v);
        crate::port::cells_set(wd, (j * 16) + k, u);
        k += 1;
    }
    return 0;
}
pub(crate) fn pc_rev_rows(mut wd: &mut crate::port::Cells, a: i32, b: i32) -> i32 {
    let mut i: i32 = a;
    let mut j: i32 = b;
    while i < j {
        pc_swap_rows(wd, i, j);
        i += 1;
        j -= 1;
    }
    return 0;
}
pub(crate) fn pc_wcls(gl: &mut crate::port::Cells, wd: &mut crate::port::Cells, w: i32) -> i32 {
    // 2 when the word has more left-to-right letters and digits than right-to-left letters.
    let g0: i32 = wd_get(wd, w, wf_gfirst());
    let gn: i32 = wd_get(wd, w, wf_gcount());
    let mut j: i32 = 0;
    let mut nr: i32 = 0;
    let mut nl: i32 = 0;
    let mut cl: i32 = 0;
    while j < gn {
        cl = pc_gcls(gl, g0 + j);
        if cl == 1 {
            nr += 1;
        }
        if cl == 2 {
            nl += 1;
        }
        j += 1;
    }
    if nr > nl {
        return 1;
    }
    return 2;
}
pub(crate) fn pc_line_bidi(mut gl: &mut crate::port::Cells, mut wd: &mut crate::port::Cells, mut ln: &mut crate::port::Cells, lidx: i32, wfst: i32, wlst: i32) -> i32 {
    // Line lidx holds words [wfst, wlst]. When more of its glyphs are right-to-left than
    // left-to-right it is a right-to-left line (`ld-rtl`); if the words run left to right on
    // the page, their ORDER is made logical: reversed, with runs of left-to-right words
    // turned back; each word's glyphs are re-pointed at it and its gap is the space to
    // the word that follows it in that order.
    let mut w: i32 = wfst;
    let mut nr: i32 = 0;
    let mut nl: i32 = 0;
    let mut j: i32 = 0;
    let mut cl: i32 = 0;
    let mut a: i32 = 0;
    let mut z: i32 = 0;
    let mut g0: i32 = 0;
    let mut gn: i32 = 0;
    while w <= wlst {
        g0 = wd_get(wd, w, wf_gfirst());
        gn = wd_get(wd, w, wf_gcount());
        j = 0;
        while j < gn {
            cl = pc_gcls(gl, g0 + j);
            if cl == 1 {
                nr += 1;
            }
            if cl == 2 {
                nl += 1;
            }
            j += 1;
        }
        w += 1;
    }
    if nr <= nl {
        return 0;
    }
    ln_set(ln, lidx, lf_dir(), ld_rtl());
    if pc_axis(gl_get(gl, wd_get(wd, wfst, wf_gfirst()), gf_rot())) != 0 {
        return 0;
    }
    if wd_get(wd, wlst, wf_x0()) < wd_get(wd, wfst, wf_x0()) {
        return 0;
    }
    if wfst == wlst {
        return 0;
    }
    pc_rev_rows(wd, wfst, wlst);
    a = wfst;
    while a <= wlst {
        if pc_wcls(gl, wd, a) == 2 {
            z = a;
            while (z < wlst) && (pc_wcls(gl, wd, z + 1) == 2) {
                z += 1;
            }
            pc_rev_rows(wd, a, z);
            a = z + 1;
        } else {
            a += 1;
        }
    }
    w = wfst;
    while w <= wlst {
        g0 = wd_get(wd, w, wf_gfirst());
        gn = wd_get(wd, w, wf_gcount());
        j = 0;
        while j < gn {
            gl_set(gl, g0 + j, gf_word(), w);
            j += 1;
        }
        z = -1;
        if w < wlst {
            z = wd_get(wd, w, wf_x0()) - wd_get(wd, w + 1, wf_x1());
        }
        wd_set(wd, w, wf_gap(), z);
        w += 1;
    }
    return 0;
}
pub fn pc_group(mut gl: &mut crate::port::Cells, mut et: &mut crate::port::Cells, mut wd: &mut crate::port::Cells, mut ln: &mut crate::port::Cells, page: i32, g0: i32, w0: i32) -> i32 {
    // Group the glyphs from g0 on into words, and the words from w0 on into lines.
    let g1: i32 = gl_count(gl);
    let mut i: i32 = g0;
    let mut cur: i32 = -1;
    while i < g1 {
        if pc_space_cp(gl_get(gl, i, gf_cp())) == 1 {
            if cur >= 0 {
                pc_emit_word(gl, et, wd, page, cur, i - 1);
                cur = -1;
            }
        } else {
            if cur >= 0 {
                if pc_continues(gl, i - 1, i) == 0 {
                    pc_emit_word(gl, et, wd, page, cur, i - 1);
                    cur = -1;
                }
            }
            if cur < 0 {
                cur = i;
            }
        }
        i += 1;
    }
    if cur >= 0 {
        pc_emit_word(gl, et, wd, page, cur, g1 - 1);
        cur = -1;
    }
    // Lines: consecutive words on one baseline, in order.
    let nw: i32 = wd_count(wd);
    let mut j: i32 = w0;
    let mut lfirst: i32 = -1;
    let mut prev: i32 = -1;
    let mut lnx: i32 = 0;
    let mut x0: i32 = 0;
    let mut y0: i32 = 0;
    let mut x1: i32 = 0;
    let mut y1: i32 = 0;
    let mut gf0: i32 = 0;
    let mut gfp: i32 = 0;
    let mut glast: i32 = 0;
    let mut axis: i32 = 0;
    let mut joins: i32 = 0;
    let mut gap: i32 = 0;
    let mut sz: i32 = 0;
    let mut off: i32 = 0;
    while j <= nw {
        joins = 0;
        if (j < nw) && (prev >= 0) {
            gf0 = wd_get(wd, j, wf_gfirst());
            gfp = wd_get(wd, prev, wf_gfirst());
            axis = pc_axis(gl_get(gl, gfp, gf_rot()));
            if pc_rot_same(gl_get(gl, gfp, gf_rot()), gl_get(gl, gf0, gf_rot())) == 1 {
                sz = gl_get(gl, gf0, gf_size());
                if gl_get(gl, gfp, gf_size()) > sz {
                    sz = gl_get(gl, gfp, gf_size());
                }
                if sz > 200000 {
                    sz = 200000;
                }
                glast = (wd_get(wd, prev, wf_gfirst()) + wd_get(wd, prev, wf_gcount())) - 1;
                off = pc_cl(pc_pair_off(gl, glast, gf0, axis));
                // The gap is between the previous word's LAST glyph and this word's first.
                gap = pc_cl(pc_pair_gap(gl, glast, gf0, axis, sz));
                if (off * 1000) <= (sz * OFFSET_PM) {
                    if (gap * 1000) >= (0 - (sz * LINE_BACK_PM)) {
                        if (gap * 1000) <= (sz * LINE_GAP_PM) {
                            joins = 1;
                        }
                    }
                }
            }
        }
        if joins == 1 {
            wd_set(wd, prev, wf_gap(), gap);
            prev = j;
        } else {
            // The line so far ends at `prev`: record it, then start a new one at j.
            if lfirst >= 0 {
                x0 = wd_get(wd, lfirst, wf_x0());
                y0 = wd_get(wd, lfirst, wf_y0());
                x1 = wd_get(wd, lfirst, wf_x1());
                y1 = wd_get(wd, lfirst, wf_y1());
                lnx = lfirst;
                while lnx <= prev {
                    if wd_get(wd, lnx, wf_x0()) < x0 {
                        x0 = wd_get(wd, lnx, wf_x0());
                    }
                    if wd_get(wd, lnx, wf_y0()) < y0 {
                        y0 = wd_get(wd, lnx, wf_y0());
                    }
                    if wd_get(wd, lnx, wf_x1()) > x1 {
                        x1 = wd_get(wd, lnx, wf_x1());
                    }
                    if wd_get(wd, lnx, wf_y1()) > y1 {
                        y1 = wd_get(wd, lnx, wf_y1());
                    }
                    lnx += 1;
                }
                gfp = wd_get(wd, lfirst, wf_gfirst());
                axis = pc_axis(gl_get(gl, gfp, gf_rot()));
                lnx = ln_new(ln, page, x0, y0, x1, y1, lfirst, (prev - lfirst) + 1, pc_offset(gl, gfp, axis));
                ln_set(ln, lnx, lf_rot(), gl_get(gl, gfp, gf_rot()));
                pc_line_bidi(gl, wd, ln, lnx, lfirst, prev);
                gfp = lfirst;
                while gfp <= prev {
                    wd_set(wd, gfp, wf_line(), lnx);
                    gfp += 1;
                }
            }
            lfirst = j;
            prev = j;
        }
        j += 1;
    }
    return 0;
}
pub(crate) fn pc_begin_page(mut cx: &mut crate::port::Cells, page: i32) -> i32 {
    // Reset everything a page owns; the fonts (the document's) stay.
    crate::port::cells_set(cx, C_PAGE, page);
    crate::port::cells_set(cx, C_WARN, 0);
    crate::port::cells_set(cx, C_OPS, 0);
    crate::port::cells_set(cx, C_ABORT, 0);
    crate::port::cells_set(cx, C_POS, 0);
    crate::port::cells_set(cx, C_END, 0);
    crate::port::cells_set(cx, C_OXN, 0);
    crate::port::cells_set(cx, C_CDEPTH, 0);
    crate::port::cells_set(cx, C_OP, 0);
    crate::port::cells_set(cx, C_RES, 0);
    crate::port::cells_set(cx, C_SLOT, -1);
    crate::port::cells_set(cx, C_DEPTH, 0);
    crate::port::cells_set(cx, C_FDEPTH, 0);
    crate::port::cells_set(cx, C_STM, 0);
    crate::port::cells_set(cx, C_MCTOP, -1);
    crate::port::cells_set(cx, C_MCDEPTH, 0);
    crate::port::cells_set(cx, C_MCBASE, 0);
    crate::port::cells_set(cx, C_MCOVER, 0);
    crate::port::cells_set(cx, C_CURMCID, -1);
    crate::port::cells_set(cx, C_CURART, 0);
    crate::port::cells_set(cx, C_INTEXT, 0);
    crate::port::cells_set(cx, C_GSBASE, 0);
    mx_ident(cx, C_TM);
    mx_ident(cx, C_TLM);
    mx_ident(cx, C_M);
    return 0;
}
pub fn pc_page(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, mut ox: &mut crate::port::Cells, mut cs: &mut crate::port::Cells, mut out: &mut crate::port::Cells, mut f0: &mut crate::port::Cells, mut f1: &mut crate::port::Cells, mut f2: &mut crate::port::Cells, mut f3: &mut crate::port::Cells, mut gl: &mut crate::port::Cells, mut et: &mut crate::port::Cells, mut sp: &mut crate::port::Cells, pg: &mut crate::port::Cells, pi: i32, page: i32, mut wd: &mut crate::port::Cells, mut ln: &mut crate::port::Cells) -> i32 {
    // Interpret page index pi of the page table pg (page number `page`, 1-based, is
    // what the evidence records): its content streams, then the words and lines.
    // Answers 0, or 7 (`need-bytes`) when the source missed: then nothing written is
    // to be used and the caller re-runs on a fresh view (D075).
    let con: i32 = pd_pg_contents(pg, pi);
    let g0: i32 = gl_count(gl);
    let w0: i32 = wd_count(wd);
    let mut el: i32 = 0;
    let mut eh: i32 = 0;
    let mut endcs: i32 = 0;
    pc_begin_page(cx, page);
    pc_base_matrix(cx, pd_pg_crop(pg, pi, 0), pd_pg_crop(pg, pi, 1), pd_pg_crop(pg, pi, 2), pd_pg_crop(pg, pi, 3), pd_pg_rotate(pg, pi));
    pc_gs_reset(cx);
    crate::port::cells_set(cx, C_RES, pd_pg_resources(pg, pi));
    crate::port::cells_drop(cs, 0);
    if con != 0 {
        if pl_kind_of(ar, con) == 8 {
            pc_append_stream(src, ar, dc, a, b, st, cx, out, cs, con);
        }
        if pl_kind_of(ar, con) == 6 {
            el = pl_first(ar, con);
            while (el != 0) && (crate::port::cells_at(cx, C_ABORT) == 0) {
                eh = pd_resolve(src, ar, dc, a, b, st, el);
                if ps_missed(src) {
                    crate::port::cells_set(cx, C_ABORT, 1);
                }
                if (eh != 0) && (pl_kind_of(ar, eh) == 8) {
                    pc_append_stream(src, ar, dc, a, b, st, cx, out, cs, eh);
                }
                el = pl_next(ar, el);
            }
        }
    }
    if crate::port::cells_at(cx, C_ABORT) == 1 {
        return 7;
    }
    endcs = crate::port::cells_len(cs);
    pc_run(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, sp, 0, endcs);
    if crate::port::cells_at(cx, C_ABORT) == 1 {
        return 7;
    }
    if ps_missed(src) {
        return 7;
    }
    pc_group(gl, et, wd, ln, page, g0, w0);
    return 0;
}
pub fn pc_document(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, mut cx: &mut crate::port::Cells, mut ox: &mut crate::port::Cells, mut cs: &mut crate::port::Cells, mut out: &mut crate::port::Cells, mut f0: &mut crate::port::Cells, mut f1: &mut crate::port::Cells, mut f2: &mut crate::port::Cells, mut f3: &mut crate::port::Cells, mut gl: &mut crate::port::Cells, mut et: &mut crate::port::Cells, mut sp: &mut crate::port::Cells, mut pg: &mut crate::port::Cells, mut wd: &mut crate::port::Cells, mut ln: &mut crate::port::Cells) -> i32 {
    // Every page of an opened document (`pd-open` has answered 0): clears `cx`,
    // then `pc-page` for each page. Answers 0, or 7 when the source missed.
    pc_init(cx, ox);
    let n: i32 = pd_pages(src, ar, dc, a, b, st, pg);
    let mut i: i32 = 0;
    let mut status: i32 = 0;
    if n < 0 {
        return 7;
    }
    while i < n {
        status = pc_page(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, sp, pg, i, i + 1, wd, ln);
        if status == 7 {
            return 7;
        }
        i += 1;
    }
    return 0;
}
